def main():
    all_pairs = []
    pair_id = 1
    total_count = sum(len(pairs) for pairs in DOMAINS.values())

    print(f"Generating {total_count} Persian-English cross-lingual pairs across {len(DOMAINS)} domains...")

    for category, pairs in DOMAINS.items():
        for fa_text, en_text in pairs:
            all_pairs.append({
                "id": f"pair_{pair_id:03d}",
                "category": category,
                "persian": fa_text,
                "english": en_text
            })
            pair_id += 1

    assert len(all_pairs) >= 300, f"Expected at least 300 pairs, got {len(all_pairs)}"

    output_path = Path("/mnt/data/mahdidev/onnx/python-ref/benchmark_300_pairs.json")
    with open(output_path, "w", encoding="utf-8") as f:
        json.dump({
            "metadata": {
                "total_pairs": len(all_pairs),
                "total_texts": len(all_pairs) * 2,
                "domains": list(DOMAINS.keys()),
                "domain_count": len(DOMAINS),
                "pairs_per_domain": 20,
                "description": "320 authentic Persian-English paired sentences (640 texts) across 16 technical domains for cross-lingual semantic evaluation of jina-embeddings-v3"
            },
            "pairs": all_pairs
        }, f, ensure_ascii=False, indent=2)

    print(f"Successfully saved {len(all_pairs)} pairs ({len(all_pairs)*2} texts) to {output_path}")

if __name__ == "__main__":
    main()
